import{_ as i,o as a,c as o,a2 as t}from"./chunks/framework.DmUgKr4u.js";const m=JSON.parse('{"title":"01 – Agentes OSINT para Empresa Ficticia","description":"01 – Agentes OSINT para Empresa Ficticia","frontmatter":{"title":"01 – Agentes OSINT para Empresa Ficticia","description":"01 – Agentes OSINT para Empresa Ficticia"},"headers":[],"relativePath":"modules/ai-agents/01-agentes-osint.md","filePath":"modules/ai-agents/01-agentes-osint.md","lastUpdated":null}'),n={name:"modules/ai-agents/01-agentes-osint.md"};function s(r,e,l,c,d,u){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="_01-–-agentes-osint-para-empresa-ficticia" tabindex="-1">01 – Agentes OSINT para Empresa Ficticia <a class="header-anchor" href="#_01-–-agentes-osint-para-empresa-ficticia" aria-label="Permalink to &quot;01 – Agentes OSINT para Empresa Ficticia&quot;">​</a></h1><blockquote><p><strong>Objetivo Principal:</strong> Al finalizar este módulo podrás usar agentes de IA y herramientas OSINT para perfilar una <strong>empresa ficticia vulnerable</strong>, desde nivel principiante hasta avanzado, y generar un informe profesional para tu portafolio.</p></blockquote><p>La empresa objetivo será siempre <strong>ficticia</strong> (por ejemplo, <code>acmebank-testing.com</code> o similar). Nunca se realizarán actividades sobre empresas reales sin autorización.</p><hr><h2 id="_1-teoria-minima-viable-tmv" tabindex="-1">1. Teoría Mínima Viable (TMV) <a class="header-anchor" href="#_1-teoria-minima-viable-tmv" aria-label="Permalink to &quot;1. Teoría Mínima Viable (TMV)&quot;">​</a></h2><ul><li><p><strong>¿Qué es OSINT?</strong> OSINT (Open Source Intelligence) es la recolección y análisis de información a partir de fuentes públicas y abiertas (internet, redes sociales, registros públicos, etc.), sin vulnerar sistemas ni romper la ley.</p></li><li><p><strong>Empresa objetivo ficticia:</strong> Trabajaremos con una empresa inventada (&quot;AcmeBank Testing&quot;) con dominios, servicios y perfiles simulados, de forma que puedas practicar sin riesgos legales.</p></li><li><p><strong>Superficie de ataque vista desde OSINT:</strong> Todo lo que un atacante puede aprender de una organización sin enviar un solo paquete malicioso: dominios, subdominios, stack tecnológico visible, errores de exposición de información, huella en redes.</p></li><li><p><strong>IA como copiloto, no como atacante:</strong> Los modelos (Perplexity, Claude, etc.) se usan para estructurar búsquedas, interpretar datos y mejorar informes, pero <strong>no sustituyen</strong> tu criterio ni ejecutan acciones por ti.</p></li><li><p><strong>Límites legales y éticos básicos:</strong></p><ul><li>Solo se usa información pública.</li><li>No se intenta explotar vulnerabilidades, solo identificarlas a nivel teórico.</li><li>Nada de fuzzing agresivo, DoS, fuerza bruta, ni acceso a datos privados.</li></ul></li></ul><hr><h2 id="_2-herramientas-del-oficio" tabindex="-1">2. Herramientas del Oficio <a class="header-anchor" href="#_2-herramientas-del-oficio" aria-label="Permalink to &quot;2. Herramientas del Oficio&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Herramienta</th><th>Caso de Uso Principal</th></tr></thead><tbody><tr><td>Perplexity / Claude</td><td>Diseñar estrategias de búsqueda, resumir resultados, redactar informes</td></tr><tr><td>Navegador web</td><td>Navegar sitio principal de la empresa ficticia</td></tr><tr><td><code>whois</code> / servicios WHOIS</td><td>Información de registro de dominio</td></tr><tr><td><code>nslookup</code> / <code>dig</code></td><td>Resolución DNS básica (IP, registros)</td></tr><tr><td>Buscadores (Google, etc.)</td><td>Búsqueda de subdominios, perfiles, noticias</td></tr><tr><td>Herramientas tipo BuiltWith / Wappalyzer</td><td>Identificar tecnologías visibles (CMS, servidor, etc.)</td></tr></tbody></table><p>No necesitas usar todas desde el primer día; se proponen por niveles.</p><hr><h2 id="_3-practica-guiada-laboratorio" tabindex="-1">3. Práctica Guiada (Laboratorio) <a class="header-anchor" href="#_3-practica-guiada-laboratorio" aria-label="Permalink to &quot;3. Práctica Guiada (Laboratorio)&quot;">​</a></h2><h3 id="prerrequisitos" tabindex="-1">Prerrequisitos <a class="header-anchor" href="#prerrequisitos" aria-label="Permalink to &quot;Prerrequisitos&quot;">​</a></h3><ul><li>[ ] Tener un navegador web.</li><li>[ ] Tener acceso a una terminal (Linux, WSL o similar) para usar <code>whois</code>, <code>nslookup</code> o herramientas equivalentes online.</li><li>[ ] Tener una cuenta en al menos un modelo IA (Perplexity, Claude, etc.).</li></ul><p>La empresa ficticia la llamaremos <strong>AcmeBank Testing</strong> (<code>acmebank-testing.com</code>) o nombre similar que tú definas en tu informe.</p><hr><h3 id="nivel-1-—-principiante-perfil-basico-de-la-empresa" tabindex="-1">Nivel 1 — Principiante: Perfil básico de la empresa <a class="header-anchor" href="#nivel-1-—-principiante-perfil-basico-de-la-empresa" aria-label="Permalink to &quot;Nivel 1 — Principiante: Perfil básico de la empresa&quot;">​</a></h3><ol><li><p><strong>Definir el escenario con IA:</strong></p><ul><li>Pide a tu modelo IA que te ayude a definir un contexto ficticio para &quot;AcmeBank Testing&quot; (qué tipo de banco es, en qué país opera, qué servicios ofrece). Aclara que es un ejercicio educativo.</li></ul></li><li><p><strong>Identificar presencia pública mínima:</strong></p><ul><li>Supón que existe <code>https://www.acmebank-testing.com</code> (no hace falta que exista de verdad para el ejercicio de documentación).</li><li>Escribe qué secciones tendría su web pública (home, login, blog, soporte, etc.).</li></ul></li><li><p><strong>Recoger datos básicos simulados:</strong></p><ul><li>Nombre de la empresa.</li><li>País y ciudad sede.</li><li>Sector (banca, fintech, etc.).</li><li>Servicios principales.</li></ul></li><li><p><strong>Documentar en una tabla:</strong></p><ul><li>Crea una tabla simple en Markdown con estos campos y rellénala con lo que definiste.</li></ul></li></ol><p><strong>Mini-entregable nivel 1:</strong> sección &quot;Perfil básico&quot; de tu informe OSINT.</p><hr><h3 id="nivel-2-—-intermedio-huella-tecnica-inicial" tabindex="-1">Nivel 2 — Intermedio: Huella técnica inicial <a class="header-anchor" href="#nivel-2-—-intermedio-huella-tecnica-inicial" aria-label="Permalink to &quot;Nivel 2 — Intermedio: Huella técnica inicial&quot;">​</a></h3><ol><li><p><strong>Dominios y subdominios (simulados):</strong></p><ul><li>Imagina posibles subdominios: <code>app.acmebank-testing.com</code>, <code>api.acmebank-testing.com</code>, <code>support.acmebank-testing.com</code>, etc.</li><li>Usa IA para que te sugiera subdominios típicos en bancos/fintech (solo a nivel teórico).</li></ul></li><li><p><strong>Stack tecnológico visible (simulado):</strong></p><ul><li>Usando BuiltWith/Wappalyzer sobre cualquier sitio similar (no ataques, solo análisis público), observa qué tipo de tecnologías salen (ej: Nginx, Cloudflare, React, etc.).</li><li>Traslada esa idea a tu empresa ficticia (ej: &quot;AcmeBank Testing probablemente usa un frontend React y un backend en Node detrás de un Nginx&quot;).</li></ul></li><li><p><strong>Mapa técnico inicial:</strong></p><ul><li>Define: <ul><li>Qué dominios/subdominios conoces.</li><li>Qué tecnologías supones (frontend/backend/infraestructura básica).</li><li>Qué servicios públicos tendría (web principal, API pública, panel de clientes, etc.).</li></ul></li></ul></li><li><p><strong>Documentar en tu informe:</strong></p><ul><li>Añade una sección &quot;Mapa técnico inicial&quot; con texto y, si quieres, un pequeño diagrama.</li></ul></li></ol><p><strong>Mini-entregable nivel 2:</strong> sección &quot;Mapa técnico inicial&quot; de tu informe OSINT.</p><hr><h3 id="nivel-3-—-avanzado-analisis-de-riesgos-osint" tabindex="-1">Nivel 3 — Avanzado: Análisis de riesgos OSINT <a class="header-anchor" href="#nivel-3-—-avanzado-analisis-de-riesgos-osint" aria-label="Permalink to &quot;Nivel 3 — Avanzado: Análisis de riesgos OSINT&quot;">​</a></h3><ol><li><p><strong>Identificar posibles riesgos OSINT:</strong></p><ul><li>Pide a la IA que te liste riesgos típicos basados en huella OSINT para bancos/fintech (ej: exposición de paneles admin, leaks en repos públicos, phishing, etc.).</li><li>Elige de 3 a 5 riesgos que tengan sentido en el contexto que tú definiste para AcmeBank Testing.</li></ul></li><li><p><strong>Analizar impacto:</strong></p><ul><li>Para cada riesgo elegido, responde: <ul><li>¿Qué podría pasar si un atacante lo explota?</li><li>¿Qué tipo de datos o sistemas se verían afectados?</li></ul></li></ul></li><li><p><strong>Proponer contramedidas (vista Purple Team):</strong></p><ul><li>Para cada riesgo, describe al menos una medida de mitigación (hardening, controles, monitoreo, capacitación, etc.).</li></ul></li><li><p><strong>Redactar informe ejecutivo + técnico ayudado por IA:</strong></p><ul><li>Pide a tu modelo IA que te ayude a estructurar el informe en: <ul><li>Resumen ejecutivo (no técnico, para directivos).</li><li>Detalle técnico (para equipo de seguridad).</li></ul></li><li>Revisa y corrige el texto: tú tienes la última palabra.</li></ul></li></ol><p><strong>Mini-entregable nivel 3:</strong> sección &quot;Análisis de riesgos OSINT&quot; con hallazgos y contramedidas.</p><hr><h2 id="_4-evidencia-y-portafolio" tabindex="-1">4. Evidencia y Portafolio <a class="header-anchor" href="#_4-evidencia-y-portafolio" aria-label="Permalink to &quot;4. Evidencia y Portafolio&quot;">​</a></h2><ul><li><p><strong>Reto final:</strong> Arma un <strong>informe único</strong> llamado por ejemplo <code>informe-osint-acmebank-testing.md</code> donde unas los tres niveles:</p><ul><li>Perfil básico de la empresa.</li><li>Mapa técnico inicial.</li><li>Análisis de riesgos OSINT con contramedidas.</li></ul></li><li><p><strong>Entregable:</strong></p><ul><li>El archivo Markdown (o PDF generado desde él) con tu informe completo.</li><li>Opcional: un post corto en LinkedIn/Medium resumiendo el ejercicio (sin mencionar empresas reales).</li></ul></li><li><p><strong>Para tu Portafolio:</strong></p><ul><li>Sube el informe a un repositorio público (por ejemplo, una carpeta <code>osint-labs/empresa-ficticia-acmebank-testing/</code>).</li><li>Incluye una breve descripción en tu <code>PORTAFOLIO.md</code> dentro de esta plataforma.</li></ul></li></ul><hr><h2 id="_5-siguiente-paso" tabindex="-1">5. Siguiente Paso <a class="header-anchor" href="#_5-siguiente-paso" aria-label="Permalink to &quot;5. Siguiente Paso&quot;">​</a></h2><p>Una vez domines este módulo, tienes dos caminos naturales:</p><p>👉 <strong>Ofensiva asistida por IA:</strong> Continúa con <code>../02-agentes-pentest/</code> para ver cómo un agente puede ayudarte a organizar fases de pentest (reconocimiento, análisis de findings, priorización), siempre manteniendo la ética profesional.</p><p>👉 <strong>Seguridad de LLM:</strong> Si te interesa más la parte de IA, salta a <code>../03-llm-security/</code> para entender riesgos y pruebas de seguridad específicos de modelos de lenguaje.</p>',35)])])}const g=i(n,[["render",s]]);export{m as __pageData,g as default};
